<?php
require_once 'includes/functions.php';require_admin();$daily=db()->query("SELECT DATE(sale_date) day,COUNT(*) bills,SUM(total_amount) revenue FROM sales GROUP BY DATE(sale_date) ORDER BY day DESC LIMIT 30")->fetchAll();$low=db()->query('SELECT name,category,quantity FROM products WHERE quantity<=5 ORDER BY quantity,name')->fetchAll();$page_title='Reports';require 'includes/header.php'; ?>
<h1>Reports &amp; Analytics</h1><div class="panel"><h2>Daily sales (latest 30 days)</h2><div class="table-wrap"><table><tr><th>Date</th><th>Number of bills</th><th>Revenue</th></tr><?php foreach($daily as $d): ?><tr><td><?= e($d['day']) ?></td><td><?= (int)$d['bills'] ?></td><td><?= money($d['revenue']) ?></td></tr><?php endforeach; ?><?php if(!$daily): ?><tr><td colspan="3">No sales data available.</td></tr><?php endif; ?></table></div></div><div class="panel"><h2>Low stock alert (5 or fewer)</h2><div class="table-wrap"><table><tr><th>Product</th><th>Category</th><th>Available quantity</th></tr><?php foreach($low as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category']) ?></td><td class="low"><?= (int)$p['quantity'] ?></td></tr><?php endforeach; ?><?php if(!$low): ?><tr><td colspan="3">No low-stock products.</td></tr><?php endif; ?></table></div></div>
<?php require 'includes/footer.php'; ?>
